-- STAGING ONLY 489: exact UID635 retry after rollback rehearsals prove all 22 canonical lines and receipt read-back.
BEGIN;SELECT pg_advisory_xact_lock(hashtextextended('pdc-staging-489-exact-uid635-retry',0));DO $g$ BEGIN IF current_user<>'postgres' OR (SELECT count(*) FROM public.pdc_staging_environment_sentinel WHERE singleton AND project_ref='cdsmnqxtyyoeoznmbidd')<>1 OR to_regclass('public.pdc_production_environment_sentinel') IS NOT NULL OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260827038000' AND name='488_null_hours_canonical_readback') OR EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version~'^[0-9]{14}$' AND version>'20260827038000') OR (SELECT count(*) FROM public.ai_email_intake WHERE id='9cb76538-ec5e-4731-81a6-def943fbae30' AND provider_uid='imap_uid:635' AND source_hash='a7d78113b6a01a0965409d8ed88f803ae8920aaa2ca733db8739ec13a81262b4' AND status='needs_review' AND linked_vehicle_id IS NULL)<>1 OR (SELECT count(*) FROM public.ai_email_attachments WHERE id='32115483-497d-4fd1-bcb1-cf3184dcc212' AND intake_id='9cb76538-ec5e-4731-81a6-def943fbae30' AND source_hash='0057cdf1cf9426c2ab53ccf04031c5a0551fd76e241e2bd1d55cfb5de5146689' AND text_extraction_status='extracted')<>1 OR EXISTS(SELECT 1 FROM public.vehicles WHERE stock_number_normalized='13000775') OR NOT EXISTS(SELECT 1 FROM public.navision_backend_records WHERE id='ed1b48fc-d423-4c38-a851-c259526ab41a' AND is_current AND canonical_vehicle_id IS NULL) OR EXISTS(SELECT 1 FROM public.pdc_email_monitor_pilot WHERE enabled OR automatic_rule_application OR automatic_authenticated_jobcards) OR EXISTS(SELECT 1 FROM public.monitored_mailboxes WHERE active) OR EXISTS(SELECT 1 FROM public.pdc_monitor_stage_activation_writers WHERE active AND revoked_at IS NULL) THEN RAISE EXCEPTION 'PDC_489_TARGET_HEAD_SCOPE_OR_CONTAINMENT_MISMATCH' USING errcode='55000';END IF;END $g$;UPDATE public.pdc_monitor_stage_activation_writers SET active=true,reason='Exact UID635-only retry after successful rollback rehearsal; no broad Inbox cycle',granted_by='8a83b715-8d79-4b0e-95b2-02b55da6e8d7',granted_at=clock_timestamp(),revoked_at=null WHERE user_id='69846ef4-a74c-4569-9e35-376cf0837888';UPDATE public.monitored_mailboxes SET active=true,test_mode=true,updated_at=clock_timestamp() WHERE mailbox_key='pdc_pmb_email';UPDATE public.pdc_email_monitor_pilot SET enabled=true,minimum_uid=635,automatic_rule_application=true,automatic_authenticated_jobcards=true,outbound_email_enabled=false,updated_at=clock_timestamp() WHERE singleton;UPDATE public.pdc_email_monitor_status SET running_status='running',gateway_instance_id='pdc-monitor-staging-pmbcontroller-hourly-v1',last_error=null,last_error_code=null,updated_at=clock_timestamp() WHERE singleton;UPDATE public.ai_email_intake SET status='received',locked_at=null,locked_by=null,claim_token=null,last_error_code=null,error_details=null,updated_at=clock_timestamp() WHERE id='9cb76538-ec5e-4731-81a6-def943fbae30' AND provider_uid='imap_uid:635' AND status='needs_review';CREATE TABLE public.pdc_uid635_exact_retry_receipts_489(receipt_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),action_key text NOT NULL UNIQUE CHECK(action_key='exact-uid635-retry-after-rehearsal'),intake_id uuid NOT NULL CHECK(intake_id='9cb76538-ec5e-4731-81a6-def943fbae30'),attachment_id uuid NOT NULL CHECK(attachment_id='32115483-497d-4fd1-bcb1-cf3184dcc212'),provider_uid text NOT NULL CHECK(provider_uid='imap_uid:635'),expected_stock text NOT NULL CHECK(expected_stock='13000775'),expected_job_card text NOT NULL CHECK(expected_job_card='J139125494'),expected_operation_count integer NOT NULL CHECK(expected_operation_count=22),processor_sha256 text NOT NULL CHECK(processor_sha256='dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba'),client_sha256 text NOT NULL CHECK(client_sha256='d19ef949179e9c96f2feb4d4795f1c42d040d54c15bf5e6615369354ad55f63e'),exact_provider_filter boolean NOT NULL CHECK(exact_provider_filter),outbound_email_enabled boolean NOT NULL CHECK(NOT outbound_email_enabled),created_at timestamptz NOT NULL DEFAULT clock_timestamp());ALTER TABLE public.pdc_uid635_exact_retry_receipts_489 ENABLE ROW LEVEL SECURITY;REVOKE ALL ON public.pdc_uid635_exact_retry_receipts_489 FROM public,anon,authenticated,service_role;INSERT INTO public.pdc_uid635_exact_retry_receipts_489(action_key,intake_id,attachment_id,provider_uid,expected_stock,expected_job_card,expected_operation_count,processor_sha256,client_sha256,exact_provider_filter,outbound_email_enabled) VALUES('exact-uid635-retry-after-rehearsal','9cb76538-ec5e-4731-81a6-def943fbae30','32115483-497d-4fd1-bcb1-cf3184dcc212','imap_uid:635','13000775','J139125494',22,'dfd493de92a86b92b2eea72763d5a067ac1092c4ddda1a2e29af39e4713adfba','d19ef949179e9c96f2feb4d4795f1c42d040d54c15bf5e6615369354ad55f63e',true,false);DO $p$ BEGIN IF (SELECT count(*) FROM public.ai_email_intake WHERE id='9cb76538-ec5e-4731-81a6-def943fbae30' AND status='received')<>1 OR EXISTS(SELECT 1 FROM public.ai_email_intake WHERE provider_uid='imap_uid:636' AND status='received') OR (SELECT count(*) FROM public.pdc_uid635_exact_retry_receipts_489)<>1 THEN RAISE EXCEPTION 'PDC_489_POSTCONDITION_FAILED' USING errcode='55000';END IF;END $p$;INSERT INTO supabase_migrations.schema_migrations(version,name,statements) VALUES('20260827039000','489_activate_exact_uid635_retry',ARRAY['Reactivate only retained intake imap_uid:635 for exact provider-filtered processing after three rollback rehearsals','Bind corrected server receipt contracts and NULL-aware runtime read-back','Do not process unrelated UID636 and do not run a broad Gmail search','No outbound email; immediate terminal containment required','Production untouched']);COMMIT;
